const items = $('Citas Nuevas (Confirmacion)').all();
if (items.length === 0) return [];
return items.map(item => {
  const b = item.json;
  const d = new Date(b.start_time);
  const days = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  const months = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const dateStr = days[d.getDay()] + ' ' + d.getDate() + ' de ' + months[d.getMonth()];
  const timeStr = d.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'America/Mexico_City' });
  const msg = '¡Tu cita fue registrada! 🎉\n\n📋 ' + (b.service_name || 'Servicio') + '\n📅 ' + dateStr + '\n⏰ ' + timeStr + '\n\nEn ' + b.tenant_name + ' te esperamos. Si necesitas cancelar o cambiar, escríbenos 😊';
  return { json: { phone: b.phone, phoneNumberId: b.phone_number_id, msg, bookingId: b.booking_id, reminderType: 'confirmacion' } };
});

const items = $('Citas en 24h').all();
if (items.length === 0) return [];
return items.map(item => {
  const b = item.json;
  const d = new Date(b.start_time);
  const timeStr = d.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'America/Mexico_City' });
  const msg = '¡Nos vemos mañana! 💅\n\nRecuerda que tienes tu cita de *' + (b.service_name || 'servicio') + '* mañana a las *' + timeStr + '* en ' + b.tenant_name + '.\n\nTe esperamos. ¡Hasta mañana! 😊';
  return { json: { phone: b.phone, phoneNumberId: b.phone_number_id, msg, bookingId: b.booking_id, reminderType: '24h' } };
});

const items = $('Citas en 1h').all();
if (items.length === 0) return [];
return items.map(item => {
  const b = item.json;
  const msg = '¡Nos vemos en una hora! ⏰\n\nTu cita de *' + (b.service_name || 'servicio') + '* es en *60 minutos* en ' + b.tenant_name + '.\n\n¡Ya casi es tu momento! 💅';
  return { json: { phone: b.phone, phoneNumberId: b.phone_number_id, msg, bookingId: b.booking_id, reminderType: '1h' } };
});

const items = $('Resumen Diario Admin (8am)').all();
if (items.length === 0) return [];
return items.map(item => {
  const r = item.json;
  const citas = typeof r.citas === 'string' ? JSON.parse(r.citas) : (r.citas || []);
  const lista = citas.map(c => '• ' + c.hora + ' — ' + c.cliente + ' (' + c.servicio + ')').join('\n');
  const msg = '🗓️ *Agenda de hoy — ' + r.tenant_name + '*\n\nTienes *' + r.total_citas + ' cita(s)* hoy:\n\n' + lista + '\n\n¡Que tengas un excelente día! 💪✨';
  return { json: { phone: r.phone, phoneNumberId: r.phone_number_id, msg, bookingId: null, reminderType: 'admin_daily', tenantSlug: r.tenant_slug } };
});
